1	package cli
2	
3	import (
4		"archive/tar"
5		"archive/zip"
6		"compress/gzip"
7		"context"
8		"crypto/sha256"
9		"encoding/hex"
10		"errors"
11		"fmt"
12		"io"
13		"net"
14		"net/http"
15		"net/url"
16		"os"
17		"path"
18		"path/filepath"
19		"runtime"
20		"strings"
21		"time"
22	)
23	
24	// Release-asset download. The one irreducibly forge-specific piece of the
25	// plugin system is where release binaries live; it's contained here as a
26	// small per-host URL convention table with a declarative escape hatch
27	// (download_url in entire-plugin.yml). Everything else — version listing,
28	// metadata, the index — runs on the git protocol.
29	
30	// errAssetNotFound distinguishes "this tag has no matching asset" (worth
31	// trying the next-highest tag — a pushed tag whose release isn't published
32	// yet) from transport errors (not worth retrying on another tag).
33	var errAssetNotFound = errors.New("no matching release asset")
34	
35	// errUnverifiedAsset means an asset was reachable but nothing authenticated
36	// it — no checksums.txt covering this platform. Distinct from
37	// errAssetNotFound so it never triggers the next-highest-tag walk: falling
38	// back to an older tag wouldn't make the download any more trustworthy.
39	var errUnverifiedAsset = errors.New("release asset cannot be verified")
40	
41	// requireSecureAssetURL gates every plugin HTTP fetch on a transport that a
42	// network attacker can't rewrite.
43	//
44	// Plaintext HTTP is not merely "less good" here: the asset and the
45	// checksums.txt that authenticates it come from the same origin, so an
46	// attacker who can rewrite one can rewrite both, and checksum verification
47	// becomes theatre. HTTPS is therefore required for anything off-machine.
48	//
49	// Loopback is exempt so httptest-backed tests and local forge experiments
50	// keep working — traffic that never leaves the machine has no network
51	// attacker to defend against.
52	func requireSecureAssetURL(rawURL string) error {
53		u, err := url.Parse(rawURL)
54		if err != nil {
55			return fmt.Errorf("parse download URL %q: %w", rawURL, err)
56		}
57		switch strings.ToLower(u.Scheme) {
58		case "https":
59			return nil
60		case "http":
61			if isLoopbackHost(u.Hostname()) {
62				return nil
63			}
64			return fmt.Errorf("refusing to download %s over plaintext HTTP: the asset and its %s would share an origin, so a network attacker could replace both and checksum verification would prove nothing; serve the release over HTTPS or declare an https download_url in %s",
65				rawURL, checksumsFileName, pluginMetadataFileName)
66		default:
67			return fmt.Errorf("plugin downloads must use https; %q has scheme %q", rawURL, u.Scheme)
68		}
69	}
70	
71	// isLoopbackHost reports whether host addresses this machine.
72	func isLoopbackHost(host string) bool {
73		if strings.EqualFold(host, "localhost") {
74			return true
75		}
76		if ip := net.ParseIP(host); ip != nil {
77			return ip.IsLoopback()
78		}
79		return false
80	}
81	
82	// pluginHTTPClient bounds the total time for a single asset download.
83	// Plugins can be tens of MB; 5 minutes is generous even on slow links.
84	var pluginHTTPClient = &http.Client{Timeout: 5 * time.Minute}
85	
86	// maxPluginAssetSize caps a downloaded asset. Real plugin binaries are tens
87	// of MB; the cap exists so a misconfigured URL serving an endless stream
88	// can't fill the disk.
89	const maxPluginAssetSize = 512 << 20 // 512 MiB
90	
91	// releaseAssetBaseURL returns the URL prefix release assets live under for
92	// the repo's host. GitHub and the Gitea family share a convention; GitLab
93	// has its own. Unknown hosts default to the GitHub-style convention (most
94	// self-hosted forges mirror it) — authors on hosts that don't can declare
95	// download_url in entire-plugin.yml.
96	func releaseAssetBaseURL(repoURL, tag string) (string, error) {
97		u, err := url.Parse(strings.TrimSuffix(repoURL, ".git"))
98		if err != nil {
99			return "", fmt.Errorf("parse repo URL: %w", err)
100		}
101		if u.Scheme != "https" && u.Scheme != "http" {
102			return "", fmt.Errorf("release downloads need an http(s) repo URL, got %q (declare download_url in %s for non-HTTP remotes)", repoURL, pluginMetadataFileName)
103		}
104		base := strings.TrimSuffix(u.String(), "/")
105		host := strings.ToLower(u.Hostname())
106		if host == "gitlab.com" || strings.HasPrefix(host, "gitlab.") {
107			return base + "/-/releases/" + url.PathEscape(tag) + "/downloads/", nil
108		}
109		return base + "/releases/download/" + url.PathEscape(tag) + "/", nil
110	}
111	
112	// expandDownloadTemplate expands the author-declared download_url template.
113	// Placeholders: {name} {tag} {version} {os} {arch} {asset}.
114	func expandDownloadTemplate(tmpl, name, tag, asset string) string {
115		r := strings.NewReplacer(
116			"{name}", name,
117			"{tag}", tag,
118			"{version}", strings.TrimPrefix(tag, "v"),
119			"{os}", runtime.GOOS,
120			"{arch}", runtime.GOARCH,
121			"{asset}", asset,
122		)
123		return r.Replace(tmpl)
124	}
125	
126	// archAliases maps a GOARCH to the spellings seen in release asset names.
127	func archAliases(goarch string) []string {
128		switch goarch {
129		case "amd64":
130			return []string{"amd64", "x86_64"}
131		case "arm64":
132			return []string{"arm64", "aarch64"}
133		default:
134			return []string{goarch}
135		}
136	}
137	
138	// osAliases maps a GOOS to asset-name spellings, most specific first.
139	// "all" covers macOS universal binaries.
140	func osAliases(goos string) []string {
141		if goos == darwinGOOS {
142			return []string{"darwin", "macos", "all"}
143		}
144		return []string{goos}
145	}
146	
147	// assetCandidates returns release asset filenames to try for this platform,
148	// in preference order: archives before raw binaries, version-in-name
149	// (goreleaser's default template) before version-less.
150	func assetCandidates(name, tag string) []string {
151		binName := pluginBinaryPrefix + name
152		version := strings.TrimPrefix(tag, "v")
153		stems := make([]string, 0, 16)
154		for _, osName := range osAliases(runtime.GOOS) {
155			for _, arch := range archAliases(runtime.GOARCH) {
156				stems = append(stems,
157					fmt.Sprintf("%s_%s_%s_%s", binName, version, osName, arch),
158					fmt.Sprintf("%s_%s_%s", binName, osName, arch),
159				)
160			}
161		}
162		exts := []string{".tar.gz", ".zip", ""}
163		if runtime.GOOS == windowsGOOS {
164			exts = []string{".zip", ".tar.gz", windowsExeExt}
165		}
166		var out []string
167		for _, ext := range exts {
168			for _, stem := range stems {
169				out = append(out, stem+ext)
170			}
171		}
172		return out
173	}
174	
175	// checksumsFileName is the conventional name of a release's checksum
176	// manifest (goreleaser's default).
177	const checksumsFileName = "checksums.txt"
178	
179	// checksumCandidates returns filenames the checksum manifest may go by.
180	func checksumCandidates(name, tag string) []string {
181		binName := pluginBinaryPrefix + name
182		version := strings.TrimPrefix(tag, "v")
183		return []string{
184			checksumsFileName,
185			fmt.Sprintf("%s_%s_checksums.txt", binName, version),
186			binName + "_checksums.txt",
187		}
188	}
189	
190	// parseChecksums parses "hex  filename" lines (sha256sum format) into a
191	// filename → digest map.
192	func parseChecksums(data []byte) map[string]string {
193		out := make(map[string]string)
194		for _, line := range strings.Split(string(data), "\n") {
195			fields := strings.Fields(line)
196			if len(fields) != 2 {
197				continue
198			}
199			// sha256sum marks binary-mode files with a leading *.
200			out[strings.TrimPrefix(fields[1], "*")] = strings.ToLower(fields[0])
201		}
202		return out
203	}
204	
205	// selectAssetFromChecksums picks the preferred candidate present in the
206	// checksum manifest. The manifest lists what was actually published, so
207	// this avoids probing candidate URLs one by one.
208	func selectAssetFromChecksums(sums map[string]string, name, tag string) (asset, digest string, ok bool) {
209		for _, c := range assetCandidates(name, tag) {
210			if d, present := sums[c]; present {
211				return c, d, true
212			}
213		}
214		return "", "", false
215	}
216	
217	// fetchedAsset is the result of downloadPluginAsset: a verified asset on
218	// disk in a caller-owned staging dir.
219	type fetchedAsset struct {
220		// Path is the downloaded asset file inside the staging dir.
221		Path string
222		// Asset is the asset filename that matched.
223		Asset string
224		// SHA256 is the hex digest of the downloaded bytes.
225		SHA256 string
226		// Verified is true when SHA256 was checked against a digest published in
227		// the release's checksum manifest, rather than merely computed from
228		// whatever arrived. Recorded in the install manifest so `plugin doctor`
229		// can surface unverified installs.
230		Verified bool
231	}
232	
233	// downloadPluginAsset locates and downloads the release asset for name@tag
234	// into stagingDir, verifying against the release's checksum manifest when
235	// one is published. Returns errAssetNotFound (possibly wrapped) when the
236	// tag has no asset for this platform.
237	func downloadPluginAsset(ctx context.Context, meta *PluginMetadata, repoURL, name, tag, stagingDir string, allowUnverified bool) (*fetchedAsset, error) {
238		assetURL := func(asset string) (string, error) {
239			if meta != nil && meta.DownloadURL != "" {
240				return expandDownloadTemplate(meta.DownloadURL, name, tag, asset), nil
241			}
242			base, err := releaseAssetBaseURL(repoURL, tag)
243			if err != nil {
244				return "", err
245			}
246			return base + asset, nil
247		}
248	
249		// A download_url template without {asset} is a single fully-specified
250		// URL; there is nothing to select — and no way to locate a checksum
251		// manifest, since every candidate name would expand to the same URL.
252		if meta != nil && meta.DownloadURL != "" && !strings.Contains(meta.DownloadURL, "{asset}") {
253			if !allowUnverified {
254				return nil, fmt.Errorf("%w: %s declares a fixed download_url with no {asset} placeholder, so no %s can be located; add {asset} to the template or install with --allow-unverified",
255					errUnverifiedAsset, pluginMetadataFileName, checksumsFileName)
256			}
257			u := expandDownloadTemplate(meta.DownloadURL, name, tag, "")
258			return fetchAndVerify(ctx, u, assetNameFromURL(u), "", stagingDir)
259		}
260	
261		// Preferred path: fetch the checksum manifest and pick from what was
262		// actually published.
263		for _, cs := range checksumCandidates(name, tag) {
264			u, err := assetURL(cs)
265			if err != nil {
266				return nil, err
267			}
268			data, err := httpGetSmall(ctx, u)
269			if err != nil {
270				continue
271			}
272			asset, digest, ok := selectAssetFromChecksums(parseChecksums(data), name, tag)
273			if !ok {
274				// This manifest lists nothing for the platform. Keep going: a
275				// stale or hand-written root checksums.txt must not mask a
276				// goreleaser manifest under another candidate name, or a
277				// published asset still reachable by the probe fallback.
278				// Falling through doesn't weaken verification — an attacker
279				// who controls the manifest could list a malicious digest
280				// directly.
281				continue
282			}
283			au, err := assetURL(asset)
284			if err != nil {
285				return nil, err
286			}
287			return fetchAndVerify(ctx, au, asset, digest, stagingDir)
288		}
289	
290		// Fallback: probe candidates directly (a release published without a
291		// checksum manifest). Nothing authenticates these bytes, so by default an
292		// asset found this way is refused rather than installed.
293		//
294		// The probe still runs when verification is required: it distinguishes
295		// "this tag has no release yet" (errAssetNotFound, worth walking down to
296		// the next tag) from "the release exists but publishes no checksums"
297		// (errUnverifiedAsset, which an older tag wouldn't fix). Getting that
298		// wrong would report a missing release for a plugin that simply doesn't
299		// ship checksums.
300		for _, asset := range assetCandidates(name, tag) {
301			u, err := assetURL(asset)
302			if err != nil {
303				return nil, err
304			}
305			fa, err := fetchAndVerify(ctx, u, asset, "", stagingDir)
306			if err == nil {
307				if !allowUnverified {
308					_ = os.Remove(fa.Path)
309					return nil, fmt.Errorf("%w: %s %s publishes %s but no %s to authenticate it; ask the author to publish checksums, or install with --allow-unverified",
310						errUnverifiedAsset, name, tag, asset, checksumsFileName)
311				}
312				return fa, nil
313			}
314			if !errors.Is(err, errAssetNotFound) {
315				return nil, err
316			}
317		}
318		return nil, fmt.Errorf("%w for %s/%s at %s %s", errAssetNotFound, runtime.GOOS, runtime.GOARCH, repoURL, tag)
319	}
320	
321	// assetNameFromURL derives the staging filename for a fully-specified
322	// download_url. Only the URL path contributes: path.Base on the whole URL
323	// folds a query string into the name ("entire-run.tar.gz?token=abc"), which
324	// then misses extractPluginBinary's extension sniff and gets written out as
325	// a raw binary — a silently broken install (and an invalid filename on
326	// Windows).
327	func assetNameFromURL(rawURL string) string {
328		if u, err := url.Parse(rawURL); err == nil && u.Path != "" {
329			return path.Base(u.Path)
330		}
331		trimmed := rawURL
332		if i := strings.IndexAny(trimmed, "?#"); i >= 0 {
333			trimmed = trimmed[:i]
334		}
335		return path.Base(trimmed)
336	}
337	
338	// httpGetSmall fetches a small text resource (checksum manifests).
339	func httpGetSmall(ctx context.Context, rawURL string) ([]byte, error) {
340		if err := requireSecureAssetURL(rawURL); err != nil {
341			return nil, err
342		}
343		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
344		if err != nil {
345			return nil, fmt.Errorf("build request for %s: %w", rawURL, err)
346		}
347		resp, err := pluginHTTPClient.Do(req)
348		if err != nil {
349			return nil, fmt.Errorf("GET %s: %w", rawURL, err)
350		}
351		defer resp.Body.Close()
352		if resp.StatusCode != http.StatusOK {
353			return nil, fmt.Errorf("GET %s: %s", rawURL, resp.Status)
354		}
355		data, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
356		if err != nil {
357			return nil, fmt.Errorf("read %s: %w", rawURL, err)
358		}
359		return data, nil
360	}
361	
362	// fetchAndVerify downloads rawURL into stagingDir, streaming the SHA-256 as
363	// it writes. A non-empty wantDigest is enforced; an empty one records the
364	// computed digest. 404/410 map to errAssetNotFound. Partial files are
365	// removed on verification failure so a hostile or truncated download never
366	// lingers in staging.
367	func fetchAndVerify(ctx context.Context, rawURL, asset, wantDigest, stagingDir string) (*fetchedAsset, error) {
368		// The asset name is normally one of our own candidates, but the
369		// single-URL download_url template path derives it from the URL and a
370		// future caller could pass a name straight from a remote manifest.
371		// Refuse anything that wouldn't stay inside stagingDir. Backslash is
372		// rejected on every platform — it's a separator on Windows, and a
373		// literal backslash in an asset name is never legitimate.
374		if asset == "" || asset == "." || asset == ".." ||
375			strings.ContainsAny(asset, `/\`) || asset != filepath.Base(asset) {
376			return nil, fmt.Errorf("unsafe release asset name %q", asset)
377		}
378		if err := requireSecureAssetURL(rawURL); err != nil {
379			return nil, err
380		}
381		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
382		if err != nil {
383			return nil, fmt.Errorf("build request for %s: %w", rawURL, err)
384		}
385		resp, err := pluginHTTPClient.Do(req)
386		if err != nil {
387			return nil, fmt.Errorf("download %s: %w", rawURL, err)
388		}
389		defer resp.Body.Close()
390		switch resp.StatusCode {
391		case http.StatusOK:
392		case http.StatusNotFound, http.StatusGone:
393			return nil, fmt.Errorf("%w: GET %s: %s", errAssetNotFound, rawURL, resp.Status)
394		default:
395			return nil, fmt.Errorf("download %s: %s", rawURL, resp.Status)
396		}
397	
398		dest := filepath.Join(stagingDir, asset)
399		out, err := os.Create(dest) //nolint:gosec // dest is inside the caller-owned staging dir; asset name came from our candidate list or checksum manifest
400		if err != nil {
401			return nil, fmt.Errorf("create staging file: %w", err)
402		}
403		h := sha256.New()
404		n, err := io.Copy(io.MultiWriter(out, h), io.LimitReader(resp.Body, maxPluginAssetSize+1))
405		closeErr := out.Close()
406		if err != nil {
407			_ = os.Remove(dest)
408			return nil, fmt.Errorf("download %s: %w", rawURL, err)
409		}
410		if closeErr != nil {
411			_ = os.Remove(dest)
412			return nil, fmt.Errorf("write staging file: %w", closeErr)
413		}
414		if n > maxPluginAssetSize {
415			_ = os.Remove(dest)
416			return nil, fmt.Errorf("download %s: exceeds %d byte limit", rawURL, int64(maxPluginAssetSize))
417		}
418		got := hex.EncodeToString(h.Sum(nil))
419		if wantDigest != "" && !strings.EqualFold(got, wantDigest) {
420			_ = os.Remove(dest)
421			return nil, fmt.Errorf("checksum mismatch for %s: got %s, want %s", asset, got, wantDigest)
422		}
423		return &fetchedAsset{Path: dest, Asset: asset, SHA256: got, Verified: wantDigest != ""}, nil
424	}
425	
426	// extractPluginBinary locates the plugin executable inside the downloaded
427	// asset and writes it to destPath (mode 0755 on Unix). Raw binaries are
428	// copied; .tar.gz/.tgz and .zip archives are searched for an entry whose
429	// basename matches entire-<name>[.exe], wherever it sits in the archive.
430	func extractPluginBinary(assetPath, name, destPath string) error {
431		binName := pluginBinaryPrefix + name
432		lower := strings.ToLower(assetPath)
433		switch {
434		case strings.HasSuffix(lower, ".tar.gz") || strings.HasSuffix(lower, ".tgz"):
435			return extractFromTarGz(assetPath, binName, destPath)
436		case strings.HasSuffix(lower, ".zip"):
437			return extractFromZip(assetPath, binName, destPath)
438		default:
439			src, err := os.Open(assetPath) //nolint:gosec // staging-dir file we just wrote
440			if err != nil {
441				return fmt.Errorf("open asset: %w", err)
442			}
443			defer src.Close()
444			return writeExecutable(src, destPath)
445		}
446	}
447	
448	// matchesPluginBinary reports whether an archive entry basename is the
449	// plugin binary, tolerating a Windows extension.
450	func matchesPluginBinary(entryName, binName string) bool {
451		base := path.Base(filepath.ToSlash(entryName))
452		if base == binName {
453			return true
454		}
455		return runtime.GOOS == windowsGOOS && strings.EqualFold(base, binName+windowsExeExt)
456	}
457	
458	// safeArchiveEntry rejects entry names that could escape an extraction
459	// root. We only ever extract a single matched file to a fixed dest, so this
460	// is defense in depth against a hostile archive masking as a plugin.
461	func safeArchiveEntry(entryName string) bool {
462		clean := path.Clean(filepath.ToSlash(entryName))
463		return !strings.HasPrefix(clean, "../") && !path.IsAbs(clean) && !strings.Contains(entryName, "\x00")
464	}
465	
466	func extractFromTarGz(archivePath, binName, destPath string) error {
467		f, err := os.Open(archivePath) //nolint:gosec // staging-dir file we just wrote
468		if err != nil {
469			return fmt.Errorf("open archive: %w", err)
470		}
471		defer f.Close()
472		gz, err := gzip.NewReader(f)
473		if err != nil {
474			return fmt.Errorf("open gzip: %w", err)
475		}
476		defer gz.Close()
477		tr := tar.NewReader(gz)
478		for {
479			hdr, err := tr.Next()
480			if errors.Is(err, io.EOF) {
481				break
482			}
483			if err != nil {
484				return fmt.Errorf("read tar: %w", err)
485			}
486			if hdr.Typeflag != tar.TypeReg || !safeArchiveEntry(hdr.Name) || !matchesPluginBinary(hdr.Name, binName) {
487				continue
488			}
489			return writeExecutable(tr, destPath)
490		}
491		return fmt.Errorf("archive %s contains no %s entry", filepath.Base(archivePath), binName)
492	}
493	
494	func extractFromZip(archivePath, binName, destPath string) error {
495		zr, err := zip.OpenReader(archivePath)
496		if err != nil {
497			return fmt.Errorf("open zip: %w", err)
498		}
499		defer zr.Close()
500		for _, f := range zr.File {
501			if f.FileInfo().IsDir() || !safeArchiveEntry(f.Name) || !matchesPluginBinary(f.Name, binName) {
502				continue
503			}
504			rc, err := f.Open()
505			if err != nil {
506				return fmt.Errorf("open zip entry: %w", err)
507			}
508			defer rc.Close()
509			return writeExecutable(rc, destPath)
510		}
511		return fmt.Errorf("archive %s contains no %s entry", filepath.Base(archivePath), binName)
512	}
513	
514	// fileSHA256 returns the hex SHA-256 of the file at path. Used to record the
515	// installed binary's digest and to re-check it in `plugin doctor`.
516	func fileSHA256(path string) (string, error) {
517		f, err := os.Open(path) //nolint:gosec // path is inside the managed plugin tree
518		if err != nil {
519			return "", fmt.Errorf("open %s: %w", filepath.Base(path), err)
520		}
521		defer f.Close()
522		h := sha256.New()
523		if _, err := io.Copy(h, f); err != nil {
524			return "", fmt.Errorf("read %s: %w", filepath.Base(path), err)
525		}
526		return hex.EncodeToString(h.Sum(nil)), nil
527	}
528	
529	// writeExecutable writes r to destPath with the executable bit set, bounded by
530	// maxPluginAssetSize. Explicit chmod (not inherited archive mode) because
531	// zip-built and raw-binary releases routinely lose the bit — the #1
532	// "downloaded plugin doesn't run" failure.
533	func writeExecutable(r io.Reader, destPath string) error {
534		return writeExecutableLimited(r, destPath, maxPluginAssetSize)
535	}
536	
537	// writeExecutableLimited is writeExecutable with an explicit cap, so the
538	// oversize path is testable without materializing 512 MiB.
539	//
540	// The cap lives here rather than in each caller's io.LimitReader because a
541	// bare LimitReader makes truncation invisible: io.Copy returns a nil error at
542	// the limit, so an archive entry larger than the cap was silently truncated
543	// and installed as the plugin binary with the install reporting success. Worse
544	// since binary_sha256 landed — the digest is computed from the truncated bytes,
545	// so `plugin doctor` would confirm the corrupt binary as intact. Reading one
546	// byte past the cap makes the overflow detectable, mirroring fetchAndVerify.
547	func writeExecutableLimited(r io.Reader, destPath string, limit int64) error {
548		out, err := os.OpenFile(destPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o755) //nolint:gosec // dest is inside the managed pkg tree; the binary must be executable
549		if err != nil {
550			return fmt.Errorf("create binary: %w", err)
551		}
552		n, err := io.Copy(out, io.LimitReader(r, limit+1))
553		if err != nil {
554			_ = out.Close()
555			_ = os.Remove(destPath)
556			return fmt.Errorf("write binary: %w", err)
557		}
558		if err := out.Close(); err != nil {
559			_ = os.Remove(destPath)
560			return fmt.Errorf("close binary: %w", err)
561		}
562		if n > limit {
563			_ = os.Remove(destPath)
564			return fmt.Errorf("plugin binary exceeds the %d byte limit", limit)
565		}
566		return nil
567	}
568

