1	package cli
2	
3	import (
4		"context"
5		"fmt"
6		"os/exec"
7		"path/filepath"
8		"runtime"
9		"strings"
10	
11		"golang.org/x/mod/semver"
12	)
13	
14	// Dependency handling is install-time only. Dispatch stays zero-cost: a
15	// plugin invokes its deps as entire-<dep> via PATH at runtime (the managed
16	// bin dir is prepended for plugin children), and `entire plugin doctor`
17	// reports drift after the fact. There is deliberately no version-range
18	// solver — requirements carry at most a minimum version.
19	
20	// maxDepDepth bounds transitive resolution. Plugin graphs are shallow in
21	// practice; the bound turns a metadata cycle that slips past the visited
22	// set (e.g. two names aliasing one repo) into an error instead of a hang.
23	const maxDepDepth = 10
24	
25	// DepAction is one planned dependency install or upgrade.
26	type DepAction struct {
27		Name       string
28		RepoURL    string
29		MinVersion string
30		// Upgrade is true when the dependency is installed but below
31		// MinVersion; the action reinstalls at the latest tag.
32		Upgrade bool
33		// CurrentTag is the installed tag for upgrades.
34		CurrentTag string
35		// FromIndex is true when the repo URL came from the index (trusted)
36		// rather than from another plugin's metadata.
37		FromIndex bool
38	}
39	
40	// DepPlan is the result of resolving a plugin's transitive requirements.
41	type DepPlan struct {
42		Actions []DepAction
43		// Warnings are non-blocking observations, e.g. a dependency satisfied
44		// from raw $PATH whose version cannot be verified.
45		Warnings []string
46	}
47	
48	// PlanDependencyInstalls resolves the transitive requirements of rootReqs
49	// into ordered install/upgrade actions. Missing dependencies must be
50	// resolvable to a repo URL via the requirement itself or the index. The
51	// visited set plus a depth bound make cycles an error path, not a hang.
52	func PlanDependencyInstalls(ctx context.Context, rootReqs []PluginRequirement, idx *PluginIndex) (*DepPlan, error) {
53		plan := &DepPlan{}
54		visited := map[string]bool{}
55		if err := planDeps(ctx, rootReqs, idx, plan, visited, 0); err != nil {
56			return nil, err
57		}
58		return plan, nil
59	}
60	
61	func planDeps(ctx context.Context, reqs []PluginRequirement, idx *PluginIndex, plan *DepPlan, visited map[string]bool, depth int) error {
62		if depth > maxDepDepth {
63			return fmt.Errorf("dependency chain deeper than %d; cycle in plugin metadata?", maxDepDepth)
64		}
65		for _, req := range reqs {
66			if visited[req.Name] {
67				continue
68			}
69			visited[req.Name] = true
70	
71			satisfied, warning, err := dependencySatisfied(req)
72			if err != nil {
73				return err
74			}
75			if warning != "" {
76				plan.Warnings = append(plan.Warnings, warning)
77			}
78			if satisfied {
79				// An already-satisfied managed dependency can itself have
80				// gaps (e.g. its own dep was removed with --force since
81				// install). Walk its recorded requirements — offline, from
82				// the manifest — so installing a parent repairs the whole
83				// chain instead of stopping at the first satisfied node.
84				// PATH/local-dev installs have no manifest; doctor covers
85				// those.
86				m, err := LoadPluginManifest(req.Name)
87				if err != nil {
88					return err
89				}
90				if m != nil {
91					if err := planDeps(ctx, m.Requires, idx, plan, visited, depth+1); err != nil {
92						return err
93					}
94				}
95				continue
96			}
97	
98			m, err := LoadPluginManifest(req.Name)
99			if err != nil {
100				return err
101			}
102			action := DepAction{Name: req.Name, MinVersion: req.MinVersion}
103			if m != nil {
104				// Installed but below min_version: upgrade in place from its
105				// recorded repo.
106				action.Upgrade = true
107				action.CurrentTag = m.Tag
108				action.RepoURL = m.RepoURL
109			} else {
110				action.RepoURL = req.RepoURL
111				if action.RepoURL == "" {
112					if e := idx.Find(req.Name); e != nil {
113						action.RepoURL = e.RepoURL
114						action.FromIndex = true
115					}
116				} else if idx.HasRepoURL(action.RepoURL) {
117					action.FromIndex = true
118				}
119				if action.RepoURL == "" {
120					return fmt.Errorf("dependency %q is not installed and has no repo URL (not in the plugin index either); add repo_url to the requirement or install it manually", req.Name)
121				}
122			}
123			plan.Actions = append(plan.Actions, action)
124	
125			// Recurse into what the dependency itself requires, using metadata
126			// only — nothing is downloaded during planning. Inspection
127			// failures don't fail the plan (the install will surface hard
128			// errors itself), but they must not be silent either: a confirmed
129			// plan that quietly omitted nested dependencies would look
130			// complete while leaving gaps for doctor to find.
131			tag := ""
132			if tags, err := listRemoteSemverTags(ctx, action.RepoURL); err == nil && len(tags) > 0 {
133				tag = tags[0]
134			}
135			if tag == "" {
136				plan.Warnings = append(plan.Warnings, fmt.Sprintf("could not list tags for %q (%s); its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", req.Name, action.RepoURL))
137				continue
138			}
139			meta, err := fetchPluginMetadataAtTag(ctx, action.RepoURL, tag)
140			if err != nil {
141				plan.Warnings = append(plan.Warnings, fmt.Sprintf("could not read %s for %q at %s; its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", pluginMetadataFileName, req.Name, tag))
142				continue
143			}
144			if meta == nil {
145				continue // no metadata file: no declared dependencies
146			}
147			if err := planDeps(ctx, meta.Requires, idx, plan, visited, depth+1); err != nil {
148				return err
149			}
150		}
151		return nil
152	}
153	
154	// dependencySatisfied checks whether a requirement is already met, in
155	// order: managed install with manifest (version-checkable) → managed entry
156	// without manifest (local-dev, version unknown) → raw $PATH (version
157	// unknown). Note `entire plugin <verb>` runs with the user's original PATH
158	// (main.go restores it for built-ins), so LookPath here sees only
159	// raw-PATH plugins — managed entries are checked explicitly first.
160	func dependencySatisfied(req PluginRequirement) (satisfied bool, warning string, err error) {
161		m, err := LoadPluginManifest(req.Name)
162		if err != nil {
163			return false, "", err
164		}
165		if m != nil {
166			if req.MinVersion == "" || semver.Compare(canonicalSemver(m.Tag), canonicalSemver(req.MinVersion)) >= 0 {
167				return true, "", nil
168			}
169			return false, "", nil // triggers the upgrade path in planDeps
170		}
171		installed, err := FindInstalledPlugin(req.Name)
172		if err != nil {
173			return false, "", err
174		}
175		if installed != nil {
176			return true, unverifiableVersionWarning(req, "a local-dev install"), nil
177		}
178		if _, err := exec.LookPath(pluginBinaryPrefix + req.Name); err == nil {
179			return true, unverifiableVersionWarning(req, "$PATH"), nil
180		}
181		return false, "", nil
182	}
183	
184	func unverifiableVersionWarning(req PluginRequirement, source string) string {
185		if req.MinVersion == "" {
186			return ""
187		}
188		return fmt.Sprintf("dependency %q is satisfied from %s; cannot verify min_version %s", req.Name, source, req.MinVersion)
189	}
190	
191	// ExecuteDepPlan runs the planned installs. Upgrades pass Force.
192	// allowUnverified is inherited from the root install so a single
193	// --allow-unverified covers the whole transitive set the user confirmed,
194	// rather than failing partway through on the first dependency without
195	// published checksums.
196	func ExecuteDepPlan(ctx context.Context, plan *DepPlan, allowUnverified bool) error {
197		for _, a := range plan.Actions {
198			if _, err := InstallPluginFromRepo(ctx, RemoteInstallOptions{
199				RepoURL: a.RepoURL, Force: a.Upgrade, AllowUnverified: allowUnverified,
200			}); err != nil {
201				return fmt.Errorf("install dependency %q: %w", a.Name, err)
202			}
203		}
204		return nil
205	}
206	
207	// DependentsOf returns the names of managed plugins whose manifests list
208	// name as a requirement — the remove guard. Computed by scanning
209	// pkg/*/manifest.yml; no extra state to maintain.
210	func DependentsOf(name string) ([]string, error) {
211		manifests, err := ListPluginManifests()
212		if err != nil {
213			return nil, err
214		}
215		var out []string
216		for _, m := range manifests {
217			for _, req := range m.Requires {
218				if req.Name == name {
219					out = append(out, m.Name)
220					break
221				}
222			}
223		}
224		return out, nil
225	}
226	
227	// PluginDoctorIssue is one problem found by RunPluginDoctor.
228	type PluginDoctorIssue struct {
229		Plugin  string
230		Problem string
231		Fix     string
232	}
233	
234	// RunPluginDoctor checks every managed plugin: bin entry present, dangling
235	// local-dev symlinks, dependency presence and min_versions, and (macOS) a
236	// quarantine attribute that would block execution.
237	func RunPluginDoctor(ctx context.Context) ([]PluginDoctorIssue, error) {
238		var issues []PluginDoctorIssue
239	
240		installed, err := ListInstalledPlugins()
241		if err != nil {
242			return nil, err
243		}
244		installedByName := map[string]*InstalledPlugin{}
245		for _, p := range installed {
246			installedByName[p.Name] = p
247			if p.Symlink {
248				if _, err := exec.LookPath(p.Path); err != nil {
249					issues = append(issues, PluginDoctorIssue{
250						Plugin:  p.Name,
251						Problem: "managed entry is a dangling or non-executable link to " + p.LinkTarget,
252						Fix:     "rebuild the target or run: entire plugin remove " + p.Name,
253					})
254				}
255			}
256			if q := quarantinedPath(ctx, p.Path); q != "" {
257				issues = append(issues, PluginDoctorIssue{
258					Plugin:  p.Name,
259					Problem: "binary carries the macOS quarantine attribute; Gatekeeper will block it",
260					Fix:     "run: xattr -d com.apple.quarantine " + q,
261				})
262			}
263		}
264	
265		manifests, err := ListPluginManifests()
266		if err != nil {
267			return nil, err
268		}
269		for _, m := range manifests {
270			if installedByName[m.Name] == nil {
271				issues = append(issues, PluginDoctorIssue{
272					Plugin:  m.Name,
273					Problem: "has an install manifest but no entry in the managed bin dir",
274					Fix:     fmt.Sprintf("reinstall: entire plugin install %s --force", m.RepoURL),
275				})
276			}
277			issues = append(issues, checkManagedBinaryIntegrity(m)...)
278			for _, req := range m.Requires {
279				satisfied, warning, err := dependencySatisfied(req)
280				if err != nil {
281					return nil, err
282				}
283				switch {
284				case satisfied && warning != "":
285					issues = append(issues, PluginDoctorIssue{Plugin: m.Name, Problem: warning, Fix: ""})
286				case !satisfied:
287					dep, depErr := LoadPluginManifest(req.Name)
288					if depErr != nil {
289						return nil, depErr
290					}
291					if dep != nil {
292						issues = append(issues, PluginDoctorIssue{
293							Plugin:  m.Name,
294							Problem: fmt.Sprintf("requires %s >= %s but %s is installed", req.Name, req.MinVersion, dep.Tag),
295							Fix:     "run: entire plugin upgrade " + req.Name,
296						})
297					} else {
298						issues = append(issues, PluginDoctorIssue{
299							Plugin:  m.Name,
300							Problem: fmt.Sprintf("requires %q, which is not installed", req.Name),
301							Fix:     "run: entire plugin install " + req.Name,
302						})
303					}
304				}
305			}
306		}
307		return issues, nil
308	}
309	
310	// checkManagedBinaryIntegrity re-hashes a managed plugin's binary and
311	// compares it to the digest recorded at install time, catching a binary
312	// swapped out under the managed directory after install.
313	//
314	// This checks the pkg/ binary, which is the copy the manifest describes and
315	// the target bin/ links to. Where the bin/ entry is a copy rather than a link
316	// (Windows without Developer Mode), a tampered copy is not covered — the
317	// dangling/non-executable link check above is what guards that surface.
318	//
319	// A manifest without BinarySHA256 predates integrity recording, so there is
320	// nothing to compare and silence is correct; nagging about it would only tell
321	// the user to reinstall a plugin that is probably fine.
322	func checkManagedBinaryIntegrity(m *PluginManifest) []PluginDoctorIssue {
323		var issues []PluginDoctorIssue
324		if m.Unverified {
325			issues = append(issues, PluginDoctorIssue{
326				Plugin:  m.Name,
327				Problem: fmt.Sprintf("installed from %s without checksum verification (the release published no %s)", m.Tag, checksumsFileName),
328				Fix:     "if the author has since published checksums, re-run: entire plugin upgrade " + m.Name,
329			})
330		}
331		if m.BinarySHA256 == "" {
332			return issues
333		}
334		dir, err := PluginPkgDir(m.Name)
335		if err != nil {
336			return issues
337		}
338		binPath := filepath.Join(dir, pluginBinaryName(m.Name))
339		got, err := fileSHA256(binPath)
