351				Problem: "managed binary no longer matches the digest recorded at install; it was modified or replaced outside entire",
352				Fix:     fmt.Sprintf("reinstall from the recorded source: entire plugin install %s --force", m.RepoURL),
353			})
354		}
355		return issues
356	}
357	
358	// quarantinedPath returns the path to flag when the file (or its symlink
359	// target) carries com.apple.quarantine. Best-effort, macOS only; any error
360	// means "not quarantined". The attribute appears when a user manually
361	// drops a browser-downloaded binary into the managed dir — CLI downloads
362	// don't set it.
363	//
