1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"os"
9		"runtime"
10		"slices"
11		"strings"
12	
13		"charm.land/huh/v2"
14		"github.com/entireio/cli/cmd/entire/cli/interactive"
15		"github.com/spf13/cobra"
16	)
17	
18	// newPluginGroupCmd builds `entire plugin` and its subcommands. The kubectl
19	// dispatcher in plugin.go is the runtime mechanism — these commands manage a
20	// per-user managed directory that the dispatcher discovers because main.go
21	// prepends it to PATH at startup.
22	func newPluginGroupCmd() *cobra.Command {
23		cmd := &cobra.Command{
24			Use:   "plugin",
25			Short: "Manage Entire plugins (install, list, upgrade, search, remove)",
26			Long: `Manage Entire plugins.
27	
28	Plugins are external executables named 'entire-<name>'. The CLI discovers
29	plugins on $PATH and from a per-user managed directory which is
30	auto-prepended to PATH at startup. The managed directory is, in order of
31	precedence:
32	
33	  $ENTIRE_PLUGIN_DIR/bin (override)
34	  $XDG_DATA_HOME/entire/plugins/bin (Linux/macOS, when set)
35	  ~/.local/share/entire/plugins/bin (Linux/macOS default)
36	  %LOCALAPPDATA%\entire\plugins\bin (Windows, when set)
37	  ~\AppData\Local\entire\plugins\bin (Windows fallback when LOCALAPPDATA is unset)
38	
39	Install sources:
40	  entire plugin install run                                    index lookup
41	  entire plugin install https://github.com/entireio/entire-run repository URL
42	  entire plugin install ./dist/entire-run                      local executable
43	
44	Remote installs resolve the newest semver tag over the git protocol, then
45	download the platform's release asset (verified against the release's
46	checksums.txt when published). Discovery uses a git-synced plugin index;
47	see 'entire plugin search' and 'entire plugin index update'.`,
48		}
49	
50		cmd.AddCommand(newPluginInstallCmd())
51		cmd.AddCommand(newPluginListCmd())
52		cmd.AddCommand(newPluginRemoveCmd())
53		cmd.AddCommand(newPluginUpgradeCmd())
54		cmd.AddCommand(newPluginSearchCmd())
55		cmd.AddCommand(newPluginInfoCmd())
56		cmd.AddCommand(newPluginBrowseCmd())
57		cmd.AddCommand(newPluginDoctorCmd())
58		cmd.AddCommand(newPluginIndexCmd())
59		return cmd
60	}
61	
62	// installArgKind classifies the install argument.
63	type installArgKind int
64	
65	const (
66		installFromPath installArgKind = iota
67		installFromURL
68		installFromIndex
69	)
70	
71	// classifyInstallArg distinguishes the three install sources. URLs are
72	// anything with a scheme or scp-like git@ prefix; paths must be explicit —
73	// a separator or a leading dot (./entire-foo) — and everything else is a
74	// bare name for index lookup. Deliberately NOT stat-based: a stray file or
75	// directory in the CWD sharing a plugin's name must not shadow the index
76	// (and could never install anyway — path installs require an entire-
77	// basename). The spaces stay disjoint because validatePluginName rejects
78	// separators in plugin names.
79	func classifyInstallArg(arg string) installArgKind {
80		if strings.Contains(arg, "://") || strings.HasPrefix(arg, "git@") {
81			return installFromURL
82		}
83		if strings.ContainsAny(arg, `/\`) || strings.HasPrefix(arg, ".") {
84			return installFromPath
85		}
86		return installFromIndex
87	}
88	
89	func newPluginInstallCmd() *cobra.Command {
90		var force, yes, noDeps, allowUnverified bool
91		var pin, indexFlag string
92		cmd := &cobra.Command{
93			Use:   "install <name|url|path>",
94			Short: "Install a plugin from the index, a git repository URL, or a local executable",
95			Long: `Install a plugin.
96	
97	Three source forms:
98	
99	  name   Bare names resolve through the plugin index:
100	             entire plugin install run
101	  url    Full git repository URLs install from any git host. The newest
102	         semver tag is resolved with 'git ls-remote'; the platform's release
103	         asset is downloaded over HTTPS and verified against the release's
104	         checksums.txt. A release that publishes no checksums is refused
105	         unless --allow-unverified is passed:
106	             entire plugin install https://github.com/entireio/entire-run
107	  path   Local executables are linked into the managed directory (symlink
108	         first, so rebuilds are picked up immediately). Paths must be
109	         explicit — a separator or leading ./ — so a stray local file can
110	         never shadow an index name:
111	             entire plugin install ./dist/entire-run
112	             entire plugin install ./entire-run
113	
114	Installing from a URL that is not listed in the plugin index asks for
115	confirmation; pass --yes to skip (required in non-interactive runs).
116	
117	Plugins may declare dependencies in entire-plugin.yml. Missing dependencies
118	are listed and installed after a single confirmation (or with --yes);
119	--no-deps opts out.`,
120			Args: cobra.ExactArgs(1),
121			RunE: func(cmd *cobra.Command, args []string) error {
122				ctx := cmd.Context()
123				arg := args[0]
124	
125				if classifyInstallArg(arg) == installFromPath {
126					p, err := InstallPluginFromPath(InstallPluginOptions{SourcePath: arg, Force: force})
127					if err != nil {
128						return fmt.Errorf("install plugin: %w", err)
129					}
130					fmt.Fprintf(cmd.OutOrStdout(), "Installed plugin %q → %s\n", p.Name, p.Path)
131					warnIfShadowsBuiltin(cmd, p.Name)
132					return nil
133				}
134				return silencePluginCancel(ctx, runRemoteInstall(ctx, cmd, arg, remoteInstallFlags{
135					force: force, yes: yes, noDeps: noDeps, allowUnverified: allowUnverified,
136					pin: pin, index: indexFlag,
137				}))
138			},
139		}
140		cmd.Flags().BoolVar(&force, "force", false, "Replace an existing entry with the same name")
141		cmd.Flags().BoolVar(&yes, "yes", false, "Skip confirmation prompts (non-index sources, dependency installs)")
142		cmd.Flags().BoolVar(&noDeps, "no-deps", false, "Do not install declared dependencies")
143		cmd.Flags().StringVar(&pin, "pin", "", "Install exactly this tag and skip it during 'plugin upgrade'")
144		cmd.Flags().StringVar(&indexFlag, "index", "", "Plugin index URL (overrides settings and "+pluginIndexEnvVar+")")
145		cmd.Flags().BoolVar(&allowUnverified, "allow-unverified", false,
146			"Install even when the release publishes no "+checksumsFileName+" to authenticate the download")
147		return cmd
148	}
149	
150	type remoteInstallFlags struct {
151		force, yes, noDeps, allowUnverified bool
152		pin, index                          string
153	}
154	
155	func runRemoteInstall(ctx context.Context, cmd *cobra.Command, arg string, flags remoteInstallFlags) error {
156		out, errOut := cmd.OutOrStdout(), cmd.ErrOrStderr()
157	
158		repoURL := arg
159		var trusted bool
160		var idx *PluginIndex
161	
162		if classifyInstallArg(arg) == installFromIndex {
163			var err error
164			idx, err = SyncPluginIndex(ctx, resolvePluginIndexURL(ctx, flags.index), false)
165			if err != nil {
166				return fmt.Errorf("resolve %q via plugin index: %w", arg, err)
167			}
168			entry := idx.Find(arg)
169			if entry == nil {
170				// Bare names never resolve to local files (see
171				// classifyInstallArg), but a user who typed one expecting a
172				// path install deserves the pointer.
173				if _, statErr := os.Stat(arg); statErr == nil {
174					return fmt.Errorf("plugin %q is not in the index; to install the local file, use an explicit path: entire plugin install ./%s", arg, arg)
175				}
176				return fmt.Errorf("plugin %q is not in the index; pass the repository URL to install from a specific repo (try 'entire plugin search %s')", arg, arg)
177			}
178			if len(entry.Platforms) > 0 && !slices.Contains(entry.Platforms, runtime.GOOS) {
179				fmt.Fprintf(errOut, "Warning: index lists %q for %s only; this is %s — continuing anyway.\n",
180					arg, strings.Join(entry.Platforms, "/"), runtime.GOOS)
181			}
182			repoURL = entry.RepoURL
183			trusted = true
184		} else {
185			// URL install: the index is only consulted for the trust check.
186			// An unreachable index degrades to "not listed" rather than
187			// blocking the install.
188			var idxErr error
189			idx, idxErr = SyncPluginIndex(ctx, resolvePluginIndexURL(ctx, flags.index), false)
190			trusted = idxErr == nil && idx.HasRepoURL(repoURL)
191		}
192	
193		if !trusted {
194			ok, err := confirmPluginAction(ctx,
195				fmt.Sprintf("Install from %s? The repository is not listed in the plugin index.", repoURL),
196				flags.yes)
197			switch {
198			case errors.Is(err, errConfirmNeedsTerminal):
199				return err // untrusted source can't proceed unconfirmed
200			case err != nil:
201				// Ctrl+C/Esc in the prompt prints "Install cancelled." and
202				// exits cleanly; real prompt failures surface wrapped.
203				return handleFormCancellation(out, "Install", err)
204			case !ok:
205				// Same outcome as an abort: nothing installed, clean exit.
206				// Exit codes must not differ between Esc and answering "No" —
207				// and automation never reaches this prompt at all (the
208				// non-interactive path fails above with the --yes hint).
209				fmt.Fprintln(out, "Install cancelled.")
210				return nil
211			}
212		}
213	
214		res, err := InstallPluginFromRepo(ctx, RemoteInstallOptions{
215			RepoURL: repoURL, Pin: flags.pin, Force: flags.force, AllowUnverified: flags.allowUnverified,
216		})
217		if err != nil {
218			return fmt.Errorf("install plugin: %w", err)
219		}
220		for _, t := range res.SkippedTags {
221			fmt.Fprintf(errOut, "Warning: tag %s has no release asset for this platform; fell back to %s.\n", t, res.Manifest.Tag)
222		}
223		fmt.Fprintf(out, "Installed plugin %q %s from %s\n", res.Manifest.Name, res.Manifest.Tag, repoURL)
224		if res.Manifest.Unverified {
225			fmt.Fprintf(errOut, "Warning: %s published no %s; the download was not authenticated.\n", res.Manifest.Tag, checksumsFileName)
226		}
227		warnIfShadowsBuiltin(cmd, res.Manifest.Name)
228	
229		if flags.noDeps || res.Metadata == nil || len(res.Metadata.Requires) == 0 {
230			return nil
231		}
232		return installPlannedDeps(ctx, cmd, res.Metadata.Requires, idx, flags)
233	}
234	
235	// installPlannedDeps plans, confirms once (apt-style), and executes
236	// dependency installs. The main plugin is already installed at this point,
237	// so a declined or non-confirmable plan degrades to a warning, not an
238	// error — doctor reports the gap afterwards.
239	func installPlannedDeps(ctx context.Context, cmd *cobra.Command, reqs []PluginRequirement, idx *PluginIndex, flags remoteInstallFlags) error {
240		out, errOut := cmd.OutOrStdout(), cmd.ErrOrStderr()
241		plan, err := PlanDependencyInstalls(ctx, reqs, idx)
242		if err != nil {
243			return fmt.Errorf("resolve dependencies: %w", err)
244		}
245		for _, w := range plan.Warnings {
246			fmt.Fprintf(errOut, "Warning: %s\n", w)
247		}
248		if len(plan.Actions) == 0 {
249			return nil
250		}
251	
252		fmt.Fprintf(out, "\nThis plugin requires %d additional plugin(s):\n", len(plan.Actions))
253		for _, a := range plan.Actions {
254			switch {
255			case a.Upgrade:
256				fmt.Fprintf(out, "  %s  (installed %s, needs >= %s — will upgrade)\n", a.Name, a.CurrentTag, a.MinVersion)
257			default:
258				fmt.Fprintf(out, "  %s  (%s)\n", a.Name, a.RepoURL)
259			}
260		}
261		ok, err := confirmPluginAction(ctx, "Install them now?", flags.yes)
262		switch {
263		case errors.Is(err, errConfirmNeedsTerminal):
264			// Non-interactive without --yes: the main install already
265			// succeeded, so skip with a pointer instead of failing late.
266			fmt.Fprintln(errOut, "Skipping dependency installs (no terminal for confirmation; re-run with --yes). 'entire plugin doctor' will report what's missing.")
267			return nil
268		case err != nil:
269			// User abort prints "Dependency install cancelled." and falls
270			// through to the skip note; real prompt failures are returned —
271			// claiming "skipped" for an error the user never saw would be
272			// misreporting.
273			if cancelErr := handleFormCancellation(errOut, "Dependency install", err); cancelErr != nil {
274				return cancelErr
275			}
276			fmt.Fprintln(errOut, "'entire plugin doctor' will report what's missing.")
277			return nil
278		case !ok:
279			fmt.Fprintln(errOut, "Skipping dependency installs; 'entire plugin doctor' will report what's missing.")
280			return nil
281		}
282		if err := ExecuteDepPlan(ctx, plan, flags.allowUnverified); err != nil {
283			return err
284		}
285		for _, a := range plan.Actions {
286			fmt.Fprintf(out, "Installed dependency %q\n", a.Name)
287		}
288		return nil
289	}
290	
291	// errConfirmNeedsTerminal signals that a confirmation was required but no
292	// terminal is available and --yes was not passed. Callers decide whether
293	// that is fatal (untrusted install) or an informed skip (dependency
294	// installs after the main install already succeeded).
295	var errConfirmNeedsTerminal = errors.New("confirmation required but no terminal available; re-run with --yes")
296	
297	// confirmPluginAction asks a yes/no question. assumeYes short-circuits;
298	// non-interactive runs without --yes return errConfirmNeedsTerminal rather
299	// than guessing. Prompt errors (including huh.ErrUserAborted on Ctrl+C/Esc)
300	// are returned raw for callers to map via handleFormCancellation.
301	func confirmPluginAction(ctx context.Context, prompt string, assumeYes bool) (bool, error) {
302		if assumeYes {
303			return true, nil
304		}
305		if !interactive.CanPromptInteractively() {
306			return false, fmt.Errorf("%w (%s)", errConfirmNeedsTerminal, prompt)
307		}
308		confirmed := false
309		form := NewAccessibleForm(huh.NewGroup(
310			huh.NewConfirm().Title(prompt).Value(&confirmed),
311		))
312		if err := form.RunWithContext(ctx); err != nil {
313			// %w keeps huh.ErrUserAborted reachable for handleFormCancellation.
314			return false, fmt.Errorf("confirm: %w", err)
315		}
316		return confirmed, nil
317	}
318	
319	// silencePluginCancel maps Ctrl+C-induced failures to a SilentError per the
320	// codebase convention (clean.go, activity_cmd.go) — printing "context
321	// canceled" at a user who just interrupted a clone or download is noise.
322	// The ctx.Err() check matters because a killed git child surfaces as
323	// "signal: killed", not context.Canceled, when the cancellation raced the
324	// subprocess.
325	func silencePluginCancel(ctx context.Context, err error) error {
326		if err == nil {
327			return nil
328		}
329		if ctx.Err() != nil || errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
330			return NewSilentError(err)
331		}
332		return err
333	}
334	
335	// warnIfShadowsBuiltin prints a one-line note to stderr when the just-installed
336	// plugin name matches a built-in command. The dispatcher's resolvePlugin gates
337	// dispatch on rootCmd.Find, so the built-in always wins at runtime — without
338	// this hint, a user who installed a shadowed plugin would silently get the
339	// built-in and have no idea their install was inert. We mirror the dispatcher's
340	// help/completion priming so names like "help" surface the warning too.
341	func warnIfShadowsBuiltin(cmd *cobra.Command, name string) {
342		root := cmd.Root()
343		if root == nil {
344			return
345		}
346		root.InitDefaultHelpCmd()
347		root.InitDefaultCompletionCmd(name)
348		if c, _, err := root.Find([]string{name}); err == nil && c != root {
349			fmt.Fprintf(cmd.ErrOrStderr(), "Note: %q shadows the built-in command; the built-in will take precedence at runtime.\n", name)
350		}
351	}
