+	}
+	return s.Plugins.IndexURL
+}
+
+// PluginIndexTTL returns the effective index freshness window (default 24h).
+func (s *EntireSettings) PluginIndexTTL() time.Duration {
+	if s == nil {
+		return 24 * time.Hour
+	}
+	return s.Plugins.IndexTTL()
